"""Validate article-level JSONL generated by parse_legal_pdf.py."""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import sys
from pathlib import Path

import pymupdf

from parse_legal_pdf import ARTICLE_RE, LEVEL_RE, article_number, clean_text

REQUIRED = ("provision_id", "law_id", "law_title", "article_no", "text", "text_raw", "source_file", "source_url", "publication_date", "effective_date", "status", "content_hash", "parser_version", "page_start", "page_end")


def validate(path: Path, source_dir: Path | None = None) -> list[str]:
    errors: list[str] = []
    seen: set[str] = set()
    previous_numbers: dict[str, int] = {}
    page_counts: dict[str, int] = {}
    lines = path.read_text(encoding="utf-8-sig").splitlines()
    if not lines:
        return ["empty dataset"]
    for line_no, raw in enumerate(lines, 1):
        try:
            item = json.loads(raw)
        except json.JSONDecodeError as exc:
            errors.append(f"line {line_no}: invalid JSON: {exc}")
            continue
        if not isinstance(item, dict):
            errors.append(f"line {line_no}: record must be an object")
            continue
        missing = [field for field in REQUIRED if item.get(field) in (None, "")]
        if missing:
            errors.append(f"line {line_no}: missing {', '.join(missing)}")
        provision_id = item.get("provision_id")
        if not isinstance(provision_id, str):
            errors.append(f"line {line_no}: provision_id must be a string")
        elif provision_id in seen:
            errors.append(f"line {line_no}: duplicate provision_id {provision_id}")
        else:
            seen.add(provision_id)
        pages = [item.get("page_start"), item.get("page_end")]
        if any(type(p) is not int or p < 1 for p in pages) or pages[0] > pages[1]:
            errors.append(f"line {line_no}: invalid page range")
        hierarchy = item.get("hierarchy_path")
        if not isinstance(hierarchy, list) or not hierarchy or any(not isinstance(h, str) or (h != "附则" and not LEVEL_RE.fullmatch(h)) for h in hierarchy):
            errors.append(f"line {line_no}: invalid/empty hierarchy_path")
        article = item.get("article_no", "")
        number = article_number(article) if isinstance(article, str) and ARTICLE_RE.fullmatch(article) else None
        law_id = item.get("law_id")
        if not isinstance(law_id, str):
            errors.append(f"line {line_no}: law_id must be a string")
        elif number is None or number != previous_numbers.get(law_id, 0) + 1:
            errors.append(f"line {line_no}: article numbering gap/out of order: {article}")
        if isinstance(law_id, str) and number is not None:
            previous_numbers[law_id] = number
        text = item.get("text")
        if isinstance(text, str):
            if hashlib.sha256(text.encode("utf-8")).hexdigest() != item.get("content_hash"):
                errors.append(f"line {line_no}: content_hash mismatch")
            if "全国人民代表大会常务委员会公报" in text or re.search(r"—\s*[０-９0-9 ]+\s*—", text):
                errors.append(f"line {line_no}: page furniture in body")
            if isinstance(item.get("text_raw"), str) and clean_text(item["text_raw"]) != text:
                errors.append(f"line {line_no}: text differs from normalized text_raw")
        else:
            errors.append(f"line {line_no}: text must be a string")
        if source_dir is not None:
            filename = item.get("source_file")
            if not isinstance(filename, str) or Path(filename).name != filename or not (source_dir / filename).is_file():
                errors.append(f"line {line_no}: source PDF missing/invalid")
            else:
                if filename not in page_counts:
                    with pymupdf.open(source_dir / filename) as pdf:
                        page_counts[filename] = len(pdf)
                if type(pages[1]) is int and pages[1] > page_counts[filename]:
                    errors.append(f"line {line_no}: page_end exceeds source PDF")
    return errors


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("jsonl", type=Path)
    parser.add_argument("--source-dir", type=Path, default=Path("data"))
    args = parser.parse_args()
    errors = validate(args.jsonl, args.source_dir)
    if errors:
        print("\n".join(errors))
        return 1
    print(f"OK: {len(args.jsonl.read_text(encoding='utf-8').splitlines())} provisions validated")
    return 0


if __name__ == "__main__":
    sys.exit(main())
